WITH with_windows AS (SELECT id, store_id, status, amount, NTILE(4) OVER (PARTITION BY status ORDER BY discount DESC, id) AS discount_bucket, CORR(discount, amount) OVER (PARTITION BY customer_id) AS corr_discount_amount, AVG(discount) OVER (PARTITION BY store_id ORDER BY shipping_fee, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) AS discount_avg_5_prior FROM orders) SELECT id, status, discount_bucket, discount_avg_5_prior, CASE WHEN status RLIKE '^(PENDING|CANCELLED)$' THEN 'GROUP_B' ELSE 'CORE' END AS status_zone FROM with_windows;
